import React, { useState, useEffect, useRef } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const NhanTin = () => {
    const [tabActive, setTabActive] = useState('all');
    const [selectedRooms, setSelectedRooms] = useState([]);
    const [message, setMessage] = useState('');

    const [chatHistory, setChatHistory] = useState(() => {
        const savedChat = localStorage.getItem('chatHistory');
        return savedChat ? JSON.parse(savedChat) : [];
    });

    const chatEndRef = useRef(null);

    // Hàm tự động cuộn xuống đáy mỗi khi có tin nhắn mới
    const scrollToBottom = () => {
        chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        localStorage.setItem('chatHistory', JSON.stringify(chatHistory));
        scrollToBottom();
    }, [chatHistory, tabActive]); // Cuộn lại khi đổi tab hoặc có tin mới

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const toggleRoom = (roomId) => {
        if (selectedRooms.includes(roomId)) {
            setSelectedRooms(selectedRooms.filter(id => id !== roomId));
        } else {
            setSelectedRooms([...selectedRooms, roomId]);
        }
    };

    const handleSendMessage = (type) => {
        if (message.trim() === '') return;

        const newMessage = {
            id: Date.now(),
            sender: "AD",
            content: message,
            type: type, 
            target: type === 'all' ? 'Tất cả' : selectedRooms.join(', '),
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setChatHistory([...chatHistory, newMessage]);
        setMessage('');
    };

    const canSendPrivate = selectedRooms.length > 0 && message.trim() !== '';

    return (
        <div style={{
            height: '100%', // Khóa chiều cao bằng với container cha
            display: 'flex', 
            flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, 
            backgroundSize: 'cover',
            backgroundPosition: 'center', 
            borderRadius: '30px',
            overflow: 'hidden', // Không cho nội dung tràn ra ngoài bo góc
            position: 'relative'
        }} className="glass-card">

            {/* 1. Header Tab: Cố định ở trên */}
            <div style={{ padding: '20px', display: 'flex', gap: '15px', flexShrink: 0 }}>
                <button 
                    onClick={() => setTabActive('all')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'all' ? '#333' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'all' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >
                    Nhắn tin chung
                </button>
                <button 
                    onClick={() => setTabActive('private')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'private' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >
                    Nhắn tin riêng
                </button>
            </div>

            {/* 2. Body: Vùng chứa nội dung chính */}
            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', overflow: 'hidden', minHeight: 0 }}>
                {tabActive === 'all' ? (
                    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                        {/* VÙNG CUỘN TIN NHẮN CHUNG */}
                        <div className="custom-scroll" style={{ 
                            flex: 1, 
                            overflowY: 'auto', 
                            padding: '10px',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: '15px'
                        }}>
                            {chatHistory.filter(m => m.type === 'all').map(msg => (
                                <div key={msg.id} style={{ display: 'flex', gap: '10px', alignItems: 'flex-start' }}>
                                    <div style={{ 
                                        minWidth: '35px', height: '35px', borderRadius: '50%', 
                                        backgroundColor: '#333', color: '#fff', display: 'flex', 
                                        alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' 
                                    }}>
                                        {msg.sender}
                                    </div>
                                    <div style={{ 
                                        backgroundColor: 'rgba(255,255,255,0.95)', padding: '12px 18px', 
                                        borderRadius: '18px 18px 18px 0', fontSize: '13px', color: '#333', maxWidth: '70%',
                                        boxShadow: '0 2px 5px rgba(0,0,0,0.05)'
                                    }}>
                                        {msg.content}
                                        <div style={{ fontSize: '9px', opacity: 0.5, marginTop: '5px', textAlign: 'right' }}>{msg.time}</div>
                                    </div>
                                </div>
                            ))}
                            <div ref={chatEndRef} /> {/* Điểm neo cuộn */}
                        </div>

                        {/* Input cố định dưới đáy Tab Chung */}
                        <div style={{ display: 'flex', gap: '10px', marginTop: '15px', flexShrink: 0 }}>
                            <input 
                                style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }} 
                                placeholder="Gửi tin nhắn đến toàn thể cư dân..." 
                                value={message}
                                onChange={(e) => setMessage(e.target.value)}
                                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage('all')}
                            />
                            <button 
                                onClick={() => handleSendMessage('all')}
                                style={{ padding: '0 30px', borderRadius: '15px', border: 'none', backgroundColor: '#333', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}
                            >
                                Gửi
                            </button>
                        </div>
                    </div>
                ) : (
                    <div style={{ flex: 1, display: 'flex', gap: '20px', minHeight: 0 }}>
                        {/* Danh sách phòng có thể cuộn độc lập */}
                        <div className="custom-scroll" style={{ 
                            width: '230px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                            gap: '6px', alignContent: 'flex-start', overflowY: 'auto', paddingRight: '5px'
                        }}>
                            {allRooms.map(room => {
                                const isSelected = selectedRooms.includes(room);
                                return (
                                    <div 
                                        key={room} 
                                        onClick={() => toggleRoom(room)}
                                        style={{ 
                                            background: isSelected ? '#8b5e5e' : 'white', 
                                            color: isSelected ? 'white' : '#333',
                                            padding: '8px 0', borderRadius: '8px', textAlign: 'center', 
                                            fontSize: '11px', fontWeight: 'bold', cursor: 'pointer',
                                            border: isSelected ? 'none' : '1px solid #ddd', transition: '0.2s'
                                        }}
                                    >
                                        {room}
                                    </div>
                                );
                            })}
                        </div>

                        {/* KHUNG CHAT RIÊNG */}
                        <div style={{ 
                            flex: 1, display: 'flex', flexDirection: 'column', 
                            backgroundColor: 'rgba(255,255,255,0.15)', borderRadius: '25px', 
                            border: '1px solid rgba(255,255,255,0.3)', padding: '15px', minHeight: 0
                        }}>
                            {/* Header phụ của chat riêng */}
                            <div style={{ color: '#fff', fontSize: '13px', marginBottom: '10px', paddingBottom: '10px', borderBottom: '1px solid rgba(255,255,255,0.2)', flexShrink: 0 }}>
                                <strong>Gửi đến:</strong> {selectedRooms.length > 0 ? selectedRooms.join(', ') : 'Chưa chọn phòng'}
                            </div>

                            {/* VÙNG CUỘN TIN NHẮN RIÊNG */}
                            <div className="custom-scroll" style={{ flex: 1, overflowY: 'auto', paddingRight: '5px' }}>
                                {chatHistory.filter(m => m.type === 'private').map(msg => (
                                    <div key={msg.id} style={{ display: 'flex', gap: '10px', marginBottom: '15px', justifyContent: 'flex-end' }}>
                                        <div style={{ 
                                            backgroundColor: '#8b5e5e', color: '#fff', padding: '10px 15px', 
                                            borderRadius: '18px 18px 0 18px', fontSize: '12px', maxWidth: '85%',
                                            boxShadow: '0 2px 8px rgba(0,0,0,0.2)'
                                        }}>
                                            <div style={{ fontSize: '9px', fontWeight: 'bold', borderBottom: '1px solid rgba(255,255,255,0.2)', marginBottom: '5px', paddingBottom: '2px', opacity: 0.8 }}>
                                                Tới: {msg.target}
                                            </div>
                                            {msg.content}
                                            <div style={{ fontSize: '8px', opacity: 0.6, marginTop: '4px', textAlign: 'right' }}>{msg.time}</div>
                                        </div>
                                    </div>
                                ))}
                                <div ref={chatEndRef} />
                            </div>

                            {/* Input nhắn riêng */}
                            <div style={{ display: 'flex', gap: '10px', marginTop: '10px', flexShrink: 0 }}>
                                <input 
                                    style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' }} 
                                    placeholder="Nhập nội dung nhắn riêng..." 
                                    value={message}
                                    onChange={(e) => setMessage(e.target.value)}
                                    onKeyPress={(e) => e.key === 'Enter' && canSendPrivate && handleSendMessage('private')}
                                />
                                <button 
                                    disabled={!canSendPrivate}
                                    onClick={() => handleSendMessage('private')}
                                    style={{ 
                                        padding: '0 25px', borderRadius: '15px', border: 'none', 
                                        backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold',
                                        opacity: canSendPrivate ? 1 : 0.4,
                                        cursor: canSendPrivate ? 'pointer' : 'not-allowed',
                                        transition: '0.3s'
                                    }}
                                >
                                    Gửi
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* CSS Tùy chỉnh thanh cuộn (Bạn có thể bỏ vào file index.css hoặc App.css) */}
            <style>{`
                .custom-scroll::-webkit-scrollbar {
                    width: 6px;
                }
                .custom-scroll::-webkit-scrollbar-track {
                    background: transparent;
                }
                .custom-scroll::-webkit-scrollbar-thumb {
                    background: rgba(0, 0, 0, 0.1);
                    border-radius: 10px;
                }
                .custom-scroll::-webkit-scrollbar-thumb:hover {
                    background: rgba(0, 0, 0, 0.2);
                }
            `}</style>
        </div>
    );
};

export default NhanTin;
